using System;using System.IO;using System.Text;using System.Collections;using System.Reflection;using UnityEngine;
public class BatchThreeUiAcceptance:MonoBehaviour {
 StringBuilder report=new StringBuilder();EntityPlayerLocal p;Delve.XUiC_ProgressionScreen screen;
 void Check(bool b,string s){if(!b)throw new Exception(s);report.AppendLine("PASS "+s);}
 void Press(string name){var b=screen.GetChildById(name) as XUiC_SimpleButton;Check(b!=null,"button "+name);typeof(XUiC_SimpleButton).GetMethod("Btn_OnPress",BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic).Invoke(b,new object[]{b,0});}
 string Binding(string key){string v="";Check(screen.GetBindingValueInternal(ref v,"dg_"+key),"binding "+key);return v;}
 void Capture(string name){Type.GetType("UnityEngine.ScreenCapture, UnityEngine.ScreenCaptureModule").GetMethod("CaptureScreenshot",new[]{typeof(string),typeof(int)}).Invoke(null,new object[]{Path.Combine(GameIO.GetUserGameDataDir(),"batch03-ui-"+name+".png"),1});}
 IEnumerator Start(){var run=Run();while(true){bool more;object current=null;try{more=run.MoveNext();if(more)current=run.Current;}catch(Exception e){report.AppendLine("FAIL "+e);break;}if(!more)break;yield return current;}File.WriteAllText(Path.Combine(GameIO.GetUserGameDataDir(),"batch03-ui-acceptance.txt"),report.ToString());Destroy(gameObject);}
 IEnumerator Run(){p=GameManager.Instance.World.GetPrimaryPlayer();p.PlayerUI.windowManager.Close("crafting");p.PlayerUI.windowManager.Close("skills");p.PlayerUI.windowManager.Open("skills",true);yield return new WaitForSeconds(1);screen=p.PlayerUI.xui.FindWindowGroupByName("skills").GetChildByType<Delve.XUiC_ProgressionScreen>();Check(screen!=null,"screen exists");Check(((XUiV_Label)screen.GetChildById("budget").ViewComponent).Text.Contains("Skill points"),"rendered budget populated on first open");
 for(int t=0;t<5;t++){Press("dg_tab"+t);yield return new WaitForSeconds(.7f);Check(Binding("attributes")== (t==0?"true":"false"),"attribute panel visibility tab "+t);Check(Binding("skills")== (t==0?"false":"true"),"skill panel visibility tab "+t);Check(!string.IsNullOrEmpty(Binding("detailtitle")),"detail title populated tab "+t);if(t>0){Check(!string.IsNullOrEmpty(Binding("nodetext0")),"perk card populated tab "+t);Press("dg_toggleMastery");Check(Binding("masteries")=="true","mastery panel opens");Press("dg_toggleMastery");}Capture(t.ToString());yield return new WaitForSeconds(.4f);}
 Press("dg_tab0");Delve.CharacterProgression.Set(p,"delveTutorialAward",1);yield return new WaitForSeconds(.7f);int skillPoints=p.Progression.SkillPoints;int attrs=Delve.CharacterProgression.UnspentAttributes(p);int level=p.Progression.GetProgressionValue("delveAttStrength").Level;report.AppendLine("BEFORE name="+p.Progression.GetProgressionValue("delveAttStrength").Name+" rank="+level+" attrs="+attrs+" canpurchase="+Binding("canpurchase")+" enabled="+((XUiC_SimpleButton)screen.GetChildById("dg_purchase")).Enabled);Press("dg_purchase");report.AppendLine("IMMEDIATE rank="+p.Progression.GetProgressionValue("delveAttStrength").Level+" msg="+Binding("message"));yield return new WaitForSeconds(.7f);Check(p.Progression.GetProgressionValue("delveAttStrength").Level==level+1,"attribute purchase increases rank");Check(p.Progression.SkillPoints==skillPoints,"attribute purchase preserves skill points");Check(Delve.CharacterProgression.UnspentAttributes(p)==attrs-1,"attribute purchase spends exactly one attribute point");
 p.PlayerUI.windowManager.Close("skills");p.PlayerUI.windowManager.Open("skills",true);yield return new WaitForSeconds(1);Check(Binding("detailstatus").Contains((level+1).ToString()),"rank retained after close/reopen");Capture("reopened");yield return new WaitForSeconds(.4f);p.PlayerUI.windowManager.Close("skills");
 p.PlayerUI.windowManager.Open("skills",true);yield return new WaitForSeconds(.5f);Press("dg_tab1");Delve.CharacterProgression.Set(p,"delvePracticeBlades",Delve.ProficiencyRules.Threshold(20));Delve.CharacterProgression.RefreshSkill(p,"Blades");yield return new WaitForSeconds(.7f);var perk=p.Progression.GetProgressionValue("delvePerkBladesBladeFamiliarity");int oldPerk=perk.Level;int oldSkill=p.Progression.SkillPoints;int oldAttrs=Delve.CharacterProgression.UnspentAttributes(p);Check(Binding("canpurchase")=="true","first combat perk available at eligible rank");Press("dg_purchase");yield return new WaitForSeconds(.7f);Check(perk.Level==oldPerk+1,"native perk purchase succeeds");Check(p.Progression.SkillPoints==oldSkill-1,"perk spends exactly one skill point");Check(Delve.CharacterProgression.UnspentAttributes(p)==oldAttrs,"perk preserves attribute points");p.PlayerUI.windowManager.Close("skills");
 foreach(string id in new[]{"delveAshSpear","delveForgedSpear","delveIronSpear"}){p.inventory.SetItem(0,ItemClass.GetItem(id,false),1);p.inventory.SetHoldingItemIdxNoHolsterTime(0);yield return new WaitForSeconds(1);var model=p.inventory.holdingItemData.model;var visual=model.GetComponent<DelvePresentation.HeldVisual>().Visual;Transform grip=null;foreach(var t in visual.GetComponentsInChildren<Transform>(true)){if(t.name=="GripRight")grip=t;}Check(Vector3.Distance(grip.position,model.position)<.0001f,id+" grip coincides with native attachment");Capture(id);yield return new WaitForSeconds(.4f);for(int action=0;action<2;action++){p.inventory.Execute(action,false,null);yield return new WaitForSeconds(.2f);Check(Vector3.Distance(grip.position,model.position)<.0001f,id+" grip retained during attack "+action);Capture(id+"-attack"+action);p.inventory.Execute(action,true,null);yield return new WaitForSeconds(1.5f);}p.SetFirstPersonView(false,false);yield return new WaitForSeconds(.5f);Capture(id+"-third-person");yield return new WaitForSeconds(.4f);p.SetFirstPersonView(true,false);yield return new WaitForSeconds(.5f);}
 report.AppendLine("PASS COMPLETE all five tabs, panel switching, attribute accounting, reopen and three spear socket alignments");}
}

